package com.johnwpb.torquewidgets;
import android.app.*;import android.appwidget.*;import android.os.*;import android.content.*;import android.widget.*;
public class GaugeSettings extends Activity {
 int id; SharedPreferences prefs; LinearLayout panel;
 EditText field(String key,String def){TextView label=new TextView(this);label.setText(key);panel.addView(label);EditText e=new EditText(this);e.setSingleLine(true);e.setText(prefs.getString(key,def));panel.addView(e);if(key.endsWith("color")){e.setFocusable(false);e.setOnClickListener(v->{LinearLayout box=new LinearLayout(this);box.setOrientation(1);SeekBar hue=new SeekBar(this),sat=new SeekBar(this),val=new SeekBar(this);TextView preview=new TextView(this);preview.setText("Selected color");float[] hsv={200,0.5f,1};try{android.graphics.Color.colorToHSV(android.graphics.Color.parseColor(e.getText().toString()),hsv);}catch(Exception ignored){}SeekBar[] bars={hue,sat,val};String[] names={"Hue","Saturation","Brightness"};for(int j=0;j<3;j++){TextView n=new TextView(this);n.setText(names[j]);box.addView(n);bars[j].setMax(j==0?359:100);bars[j].setProgress(Math.round(hsv[j]*(j==0?1:100)));box.addView(bars[j]);}box.addView(preview);Runnable refresh=()->preview.setBackgroundColor(android.graphics.Color.HSVToColor(new float[]{hue.getProgress(),sat.getProgress()/100f,val.getProgress()/100f}));for(SeekBar bar:bars)bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean u){refresh.run();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});refresh.run();new AlertDialog.Builder(this).setTitle(key).setView(box).setNegativeButton("Cancel",null).setPositiveButton("OK",(d,w)->e.setText(String.format("#%06X",0xffffff & android.graphics.Color.HSVToColor(new float[]{hue.getProgress(),sat.getProgress()/100f,val.getProgress()/100f})))).show();});}return e;}
 public void onCreate(Bundle b){super.onCreate(b);id=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);setResult(RESULT_CANCELED);if(id<0){LinearLayout l=new LinearLayout(this);l.setOrientation(1);TextView t=new TextView(this);t.setText("Torque Widgets — add independent gauges from your home screen widget picker.");l.addView(t);setContentView(l);return;}prefs=getSharedPreferences("gauge"+id,0);ScrollView scroll=new ScrollView(this);panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(24,24,24,24);scroll.addView(panel);setContentView(scroll);
 String[] keys={"Name","PID","Minimum","Maximum","Units","Multiplier","Offset","Font color","Tick color","Indicator color"};String[] defaults={"Coolant","05","0","260","°F","1.8","32","#84D5FF","#84D5FF","#84D5FF"};EditText[] fields=new EditText[keys.length];for(int i=0;i<keys.length;i++)fields[i]=field(keys[i],defaults[i]);Switch circle=new Switch(this);circle.setText("Circular gauge (off = semicircle)");circle.setChecked(prefs.getBoolean("circle",false));panel.addView(circle);Switch info=new Switch(this);info.setText("Display information only");info.setChecked(prefs.getBoolean("info",false));panel.addView(info);Spinner style=new Spinner(this);style.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Illuminated segments","Sweeping needle","Continuous arc","None"}));style.setSelection(prefs.getInt("style",0));panel.addView(style);Button save=new Button(this);save.setText("Save");panel.addView(save);save.setOnClickListener(v->{try{float min=Float.parseFloat(fields[2].getText().toString()),max=Float.parseFloat(fields[3].getText().toString());if(!Float.isFinite(min)||!Float.isFinite(max)||max<=min)throw new Exception();for(int i=5;i<7;i++)if(!Float.isFinite(Float.parseFloat(fields[i].getText().toString())))throw new Exception();for(int i=7;i<10;i++)android.graphics.Color.parseColor(fields[i].getText().toString());if(fields[1].getText().toString().trim().isEmpty())throw new Exception();SharedPreferences.Editor ed=prefs.edit();for(int i=0;i<keys.length;i++)ed.putString(keys[i],fields[i].getText().toString().trim());ed.putBoolean("circle",circle.isChecked()).putBoolean("info",info.isChecked()).putInt("style",style.getSelectedItemPosition()).apply();Intent result=new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);setResult(RESULT_OK,result);sendBroadcast(new Intent(this,CoolantWidget.class).setAction(AppWidgetManager.ACTION_APPWIDGET_UPDATE).putExtra(AppWidgetManager.EXTRA_APPWIDGET_IDS,new int[]{id}));finish();}catch(Exception ex){Toast.makeText(this,"Check range, conversion and hex colors",Toast.LENGTH_LONG).show();}});}
}